with.prompt:
REQUEST:
{{ $('Envelope In').first().json.payload.text }}

SOURCE: {{ $('Envelope In').first().json.payload.source_channel }}
LOCALE: {{ $('Envelope In').first().json.locale }}
AUTONOMY CEILING: {{ $('Envelope In').first().json.policy.autonomy_level }}

with.code:
const brief = $json.output || $json;
const env = $('Envelope In').first().json;
const errors = [];

if (!brief.objective) errors.push('objective missing');
if (!brief.offer?.name) errors.push('offer.name missing');
if (!Array.isArray(brief.channels) || !brief.channels.length) errors.push('channels empty');

// A regulated claim forces the compliance profile up regardless of what the model chose.
const regulated = (brief.message?.key_claims || []).some(c => c.risk === 'regulated');
if (regulated) {
  brief.constraints = brief.constraints || {};
  if (brief.constraints.compliance_profile === 'none' || !brief.constraints.compliance_profile) {
    brief.constraints.compliance_profile = 'standard';
  }
}

return [{ json: {
  ...brief,
  brief_id: brief.brief_id || ('brf_' + env.trace_id.slice(0, 12)),
  tenant_id: env.tenant_id,
  brand_id: env.brand_id ?? null,
  vertical: env.vertical || 'generic',
  source: { channel: env.payload?.source_channel || 'api', raw_ref: env.payload?.raw_ref ?? null, received_at: new Date().toISOString() },
  confidence: typeof brief.confidence === 'number' ? brief.confidence : 0.5,
  _validation: { ok: errors.length === 0, errors, regulated_claims_present: regulated }
} }];
